import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';

// Shared credentials stay between the NTA website server and Core.
// Origin, public site keys, and browser-supplied roles do not grant access.
async function hasTrustedCoreBridge(req) {
  const expected = String(Deno.env.get('NTA_CORE_BRIDGE_SECRET') || '').trim();
  const supplied = req.headers.get('x-nta-core-bridge-secret') || '';
  if (expected.length < 32 || supplied.length !== expected.length) return false;
  const encoder = new TextEncoder();
  const left = new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(expected)));
  const right = new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(supplied)));
  let difference = 0;
  for (let i = 0; i < left.length; i++) difference |= left[i] ^ right[i];
  return difference === 0;
}

async function readBoundedCorePayload(req) {
  if (Number(req.headers.get('content-length') || 0) > 48000) return null;
  const text = await req.text();
  if (text.length > 48000) return null;
  try {
    const payload = JSON.parse(text || '{}');
    return payload && typeof payload === 'object' && !Array.isArray(payload) ? payload : null;
  } catch { return null; }
}

const base44 = createClientFromRequest(req);
const user = await base44.auth.me().catch(() => null);
if (user?.role !== 'admin' && user?.is_service !== true && !await hasTrustedCoreBridge(req)) {
  return Response.json({ error: 'Unauthorized.' }, { status: 401 });
}
const payload = await readBoundedCorePayload(req);
if (!payload) return Response.json({ error: 'Invalid or oversized request body.' }, { status: 400 });
if (payload.connection_check === true && Object.keys(payload).length === 1) {
  return Response.json({ connection_ready: true, function: 'ntaUnifiedIntake' });
}

